class Wrapper<T> {
  T value;

  Wrapper(T value){
    this.value = value;
  }

  public String toString(){
    return "<" + value + ">";
  }
}

class Main {
  static void run(){
    Wrapper<Integer> wInt = new Wrapper<Integer>(10);
    Wrapper<Double> wDouble = new Wrapper<Double>(10.23);
    Wrapper<String> wString = new Wrapper<String>("abc");

    print(wInt);
    print(wDouble);
    print(wString);
  }
}
